shell_requests.command:
python3 -B -m unittest discover -s tests 2>&1 | tail -4; for rev in HEAD INDEX; do d=$(mktemp -d); if [ $rev = HEAD ]; then git archive HEAD app.py config.py formatting.py stats.py | tar -x -C $d; else git checkout-index --prefix=$d/ app.py config.py formatting.py stats.py; fi; echo "== $rev"; (cd $d && python3 -B -c '
from app import report
for args in [([],False),([2,4],False),([2,4],True),([1,2],True),([],True)]:
    try: print(args, repr(report(*args)))
    except Exception as e: print(args, type(e).__name__, e)
'); rm -rf $d; done
